package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityOwnerLimitExceededException;

/**
 * Rejects creating an owner when the owner's city already holds {@value #CITY_CAPACITY} or more
 * owners. A city at capacity is rejected 409 via {@link CityOwnerLimitExceededException}.
 */
public class CheckOwnerCityCapacity {

    static final int CITY_CAPACITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityOwnerLimitExceededException {
        String city = request.getCity();
        if (countInCity(ownerRepository, city) >= CITY_CAPACITY) {
            throw new CityOwnerLimitExceededException(
                    "City " + city + " already has " + CITY_CAPACITY + " or more owners");
        }
    }

    /** Existing owners whose city equals {@code city} case-insensitively, backing the 409 gate. */
    private static long countInCity(OwnerRepository ownerRepository, String city) {
        return ownerRepository.findAll().stream()
                .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
                .count();
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Derives the owner's {@code capacityWarning} at response time: {@code true} when the owner's city
 * already holds between {@value #WARN_THRESHOLD} and {@link CheckOwnerCityCapacity#CITY_CAPACITY}-1
 * owners (inclusive) — the band approaching the hard capacity limit that
 * {@link CheckOwnerCityCapacity} enforces — otherwise {@code false}. The per-city count uses the
 * same case-insensitive match as the capacity gate, so the warning provably tracks the same
 * population that the 409 rejection governs.
 *
 * <p>Wired into both the create pipeline (where the signal originates) and the single-owner GET
 * pipeline, mirroring {@link DeriveOwnerBulkSignupWarning}, so {@code capacityWarning} is populated
 * (never null) on reads as well as on the create response. The flag is transient and set on the
 * in-flight owner so the responder carries it; it is not persisted.
 */
public class DeriveOwnerCapacityWarning {

    static final int WARN_THRESHOLD = 40;

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String city = owner.getCity();
        long inCity = ownerRepository.findAll().stream()
                .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
                .count();
        owner.setCapacityWarning(inCity >= WARN_THRESHOLD && inCity < CheckOwnerCityCapacity.CITY_CAPACITY);
    }
}

